import subprocess
import shlex

@app.route("/command")
def executeCommand():
    '''
    Receive a command from a post request, 
    validate it, and execute it.
    '''
    if request.method != 'POST':
        return "Method not allowed", 405

    command = request.form.get('command')
    if not command:
        return "No command provided", 400

    # Validate command - only allow safe commands
    allowed_commands = ['ls', 'pwd', 'whoami', 'date', 'echo']
    cmd_parts = shlex.split(command)

    if not cmd_parts:
        return "Invalid command", 400

    if cmd_parts[0] not in allowed_commands:
        return f"Command '{cmd_parts[0]}' not allowed", 403

    try:
        # Execute the command with timeout
        result = subprocess.run(
            cmd_parts,
            capture_output=True,
            text=True,
            timeout=5,
            shell=False
        )

        if result.returncode == 0:
            return result.stdout, 200
        else:
            return f"Error: {result.stderr}", 400

    except subprocess.TimeoutExpired:
        return "Command execution timed out", 408
    except Exception as e:
        return f"Execution error: {str(e)}", 500
